    public class ICInventoryEstimatesController : BaseBusinessController
    {
        public ICInventoryEstimatesController()
        {
            dal = new DALBaseProvider("ICInventoryEstimates", typeof(ICInventoryEstimatesInfo));
        }
        public DataSet GetInventoryEstimateListDatasetByListOfBranchID(
                                string invoiceNo,
                                string invoiceName,
                                DateTime? fromDate,
                                DateTime? toDate,
                                int? stockID,
                                int? departID,
                                int? productGroupID,
                                int? productID,
                                int? employeeID,
                                List<BRBranchsInfo> branchList)
        {
            DataSet rtn = new DataSet();
            foreach (BRBranchsInfo ojbBranchsInfo in branchList)
            {
                DataSet ds = GetInventoryEstimateListDataset(invoiceNo,invoiceName,
                                                    fromDate,
                                                    toDate,
                                                    ojbBranchsInfo.BRBranchID,
                                                    stockID,
                                                    departID,
                                                    productGroupID,
                                                    productID,
                                                    employeeID);
                rtn.Merge(ds);
            }

            return rtn;
        }
        public DataSet GetInventoryEstimateListDataset(
                                string invoiceNo,
                                string invoiceName,
                                DateTime? fromDate,
                                DateTime? toDate,
                                int? branchID,
                                int? stockID,
                                int? departID,
                                int? productGroupID,
                                int? productID,
                                int? employeeID)
        {
            return dal.GetDataSet("ICInventoryEstimates_GetInventoryEstimateListDataset",
                                invoiceNo,
                                invoiceName,
                                fromDate,
                                toDate,
                                branchID,
                                stockID,
                                departID,
                                productGroupID,
                                productID,
                                employeeID);
        }
        public List<ICInventoryEstimatesInfo> GetAllInventoryEstimateList()
        {
            DataSet ds = dal.GetDataSet("ICInventoryEstimates_GetAllInventoryEstimateList");
            List<ICInventoryEstimatesInfo> InventoryEstimateList = new List<ICInventoryEstimatesInfo>();
            foreach (DataRow dr in ds.Tables[0].Rows)
            {
                ICInventoryEstimatesInfo objInventoryEstimateInfo = (ICInventoryEstimatesInfo)GetObjectFromDataRow(dr);
                InventoryEstimateList.Add(objInventoryEstimateInfo);
            }
            return InventoryEstimateList;
        }
    }
    #endregion
}